{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Verapamil absolute oral bioavailability in humans was 34%, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "In 20 normal young men, verapamil absolute bioavailability averaged 19.4% after oral doses versus IV, a borderline value just below the 20% threshold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C21"],
      "claim": "Praziquantel oral bioavailability in patients with hepatic cirrhosis was 27.2 ± 5.4%, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Noscapine absolute oral bioavailability in healthy volunteers was 30%, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Sulpiride absolute oral bioavailability was 34.0 ± 12.5% versus IV in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Encainide absolute oral bioavailability in normal subjects was 32 ± 7%, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Across five high-transfer analogues, absolute oral bioavailability is consistently ≥20% in healthy or normal subjects: verapamil ~22–38%, praziquantel ~27%, noscapine ~30%, sulpiride ~27–35%, and encainide ~20–42%. One verapamil study reported 19.4%, just below threshold, but the weight of direct absolute-bioavailability measurements supports F ≥ 20%.",
  "evidence_gaps": [
    "No direct experimental measurement of absolute oral bioavailability for the query molecule; prediction relies on transferable evidence from analogues.",
    "Some records report values near the 20% threshold (e.g., 19.4%, 18–20%), introducing borderline uncertainty.",
    "Disease-state conditions such as cirrhosis can increase bioavailability and may not reflect normal healthy-subject values."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

